      return;
    }
    setTournament(newEvent(accepted));
    publish(`Now playing: ${accepted[0]}`);
  }
  function finish(result: Result) {
    if (!tournament || tournament.phase !== 'playing') return;
    const next = recordResult(tournament, result);
    setTournament(next);
    if (next.phase === 'complete') {
      const items = [next, ...history.items].slice(0, 10);
      const saved = saveHistory(items);
      setHistory({ items, blocked: history.blocked || !saved.saved });
      publish(`Champion: ${next.names[next.matches.at(-1)![0]!.winner! - 1]}`);
    }
  }
  function requestLeave(action: () => void) {
    if (tournament && tournament.phase !== 'complete') setPending(() => action);
    else action();
  }
  function exportCurrent() {
    const value =
      tournament?.phase === 'playing'
        ? { ...tournament, snapshot: turnRef.current?.snapshot() ?? null }
        : tournament;
    setJson(exportTournament(value));
    publish('Tournament exported.');
  }
  function load() {
    const result = readTournament(json);
    if (result.error) {
      publish(result.error);
      return;
    }
    requestLeave(() => {
      setTournament(result.value ?? null);
      publish('Tournament loaded.');
    });
  }
  const match = tournament?.matches[tournament.currentRound]?.[tournament.currentMatch];
  const player = match && tournament ? tournament.names[match.players[tournament.turn]! - 1] : '';
  return (
    <main className="tournament-screen">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={announcement}>{notice}</span>
        </p>
      </div>
      {!tournament && (
        <>
          <label htmlFor="players">Players </label>
          <select
            id="players"
            className="control"
            value={count}
            onChange={(event) => setCount(Number(event.currentTarget.value))}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
          <div className="player-fields">
            {names.slice(0, count).map((name, index) => (
              <label key={index}>
                Player {index + 1}
                <input
                  className="control"
                  value={name}
                  onChange={(event) =>
                    setNames(names.map((n, i) => (i === index ? event.currentTarget.value : n)))
                  }
                />
              </label>
            ))}
          </div>
          <div className="tournament-actions">
            <button className="control" type="button" onClick={start}>
              Start tournament
            </button>
            <button className="control" type="button" onClick={back}>
              Back to game
            </button>
          </div>
        </>
      )}
      {tournament && match && (
        <>
          {tournament.phase === 'complete' ? (
            <>
              <p>Champion: {tournament.names[match.winner! - 1]}</p>
              <div className="tournament-actions">
                <button className="control" type="button" onClick={back}>
                  Back to game
                </button>
              </div>
            </>
          ) : (
            <>
              <p>Round: {roundName(tournament.matches[tournament.currentRound]!.length)}</p>
              <p>Now playing: {player}</p>
              <div className="tournament-actions">
                {tournament.phase === 'ready' && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setTournament({ ...tournament, phase: 'playing' });
                      publish(`Now playing: ${player}`);
                    }}
                  >
                    Start turn
                  </button>
                )}
                {tournament.phase === 'turnEnd' && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      const next = nextTurn(tournament);
                      setTournament(next);
                      publish(`Now playing: ${next.names[match.players[1]! - 1]}`);
                    }}
                  >
                    Next turn
                  </button>
                )}
                {tournament.phase === 'matchEnd' && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      const next = nextMatch(tournament);
                      setTournament(next);
                      const seed = next.matches[next.currentRound]![next.currentMatch]!.players[0]!;
                      publish(`Now playing: ${next.names[seed - 1]}`);
                    }}
                  >
                    Next match
                  </button>
                )}
                <button className="control" type="button" onClick={() => requestLeave(back)}>
                  Leave tournament
                </button>
              </div>
              {tournament.phase === 'playing' && (
                <Turn
                  key={`${tournament.currentRound}-${tournament.currentMatch}-${tournament.turn}`}
                  ref={turnRef}
                  code={match.code}
                  snapshot={tournament.snapshot}
                  onResult={finish}
                  onFeedback={(text) => {
                    if (text) publish(text);
                  }}
                />
              )}
            </>
          )}
          <Bracket tournament={tournament} />
        </>
      )}
      <section className="tournament-json">
        <h3>Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          value={json}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button className="control" type="button" onClick={exportCurrent}>
            Export tournament
          </button>
          <button className="control" type="button" onClick={load}>
            Load tournament
          </button>
        </div>
      </section>
      <section>
        <h3>Past tournaments</h3>
        {history.blocked && <p>Progress won't be saved on this device.</p>}
        {history.items.length === 0 ? (
          <p>No past tournaments yet.</p>
        ) : (
          history.items.map((item, i) => (
            <details key={i}>
              <summary>Champion: {item.names[item.matches.at(-1)![0]!.winner! - 1]}</summary>
              <Bracket tournament={item} />
              <button
                className="control"
                type="button"
                onClick={() => {
                  setJson(exportTournament(item));
                  publish('Tournament exported.');
                }}
              >
                Export tournament
              </button>
            </details>
          ))
        )}
      </section>
      {pending && (
        <LeaveDialog
          keep={() => setPending(null)}
          leave={() => {
            setPending(null);
            pending();
          }}
        />
      )}
    </main>
  );
}

